WITH enriched AS (SELECT id, store_id, product_id, sale_date, units, revenue, COUNT(revenue) OVER (PARTITION BY store_id) AS store_id_count_revenue, SUM(revenue) OVER (PARTITION BY product_id, store_id ORDER BY sale_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue, AVG(revenue) OVER (ORDER BY revenue ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS revenue_avg_2_prior, LEAD(revenue, 2) OVER (PARTITION BY product_id ORDER BY revenue ASC, id ASC) AS next_revenue FROM store_sales) SELECT id, sale_date, revenue, store_id_count_revenue, running_revenue, revenue_avg_2_prior, next_revenue FROM enriched ORDER BY sale_date ASC
